//! Fibonacci — overflows for n >= 47 with u32.

/// Compute the nth Fibonacci number.
/// BUG: uses u32 — overflows for n >= 47 in debug, wraps in release.
pub fn fibonacci(n: u32) -> u32 {
    match n {
        0 => 0,
        1 => 1,
        _ => fibonacci(n - 1) + fibonacci(n - 2), // BUG: u32 overflow at n=47
    }
}

