#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_small_fibonacci() {
        assert_eq!(fibonacci(0), 0);
        assert_eq!(fibonacci(1), 1);
        assert_eq!(fibonacci(2), 1);
        assert_eq!(fibonacci(5), 5);
        assert_eq!(fibonacci(10), 55);
    }

    #[test]
    fn test_large_fibonacci() {
        // This would panic with u32 due to overflow
        assert_eq!(fibonacci(50), 12586269025);
    }

    #[test]
    fn test_fibonacci_checked_valid() {
        assert_eq!(fibonacci_checked(10), Some(55));
        assert_eq!(fibonacci_checked(0), Some(0));
    }

    #[test]
    fn test_fibonacci_checked_overflow() {
        // Fibonacci(93) is the last that fits in u64
        assert!(fibonacci_checked(93).is_some());
        assert!(fibonacci_checked(94).is_none());
    }
}
